package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.util.*;
/** Past-only episodic retrieval with trained diagonal categorical distance. No future neighbors. */
public final class FamilyF11KernelR26 implements OnlineModelsSU2.Model {
    private static final int CAP=256;private final int[][] keys=new int[CAP][10],labels=new int[CAP][10];private final double[] metric=new double[10];private int[] previous;private int size,next;private long t;private final double lr;
    public FamilyF11KernelR26(double lr){if(!Double.isFinite(lr)||lr<=0||lr>.1)throw new IllegalArgumentException("F11_LR");this.lr=lr;Arrays.fill(metric,1);}
    public int stateWidth(){return 2;}
    private double[] weights(){double[] w=new double[size];if(previous==null||size==0)return w;double max=-1e30,z=0;for(int i=0;i<size;i++){double s=0;for(int q=0;q<10;q++)if(keys[i][q]!=previous[q])s-=metric[q];w[i]=s;max=Math.max(max,s);}for(int i=0;i<size;i++){w[i]=Math.exp(w[i]-max);z+=w[i];}for(int i=0;i<size;i++)w[i]/=z;return w;}
    private double[][] table(double[] w){double[][] p=new double[10][10];for(double[] row:p)Arrays.fill(row,.01);if(previous==null||size==0){for(double[] row:p)Arrays.fill(row,.1);return p;}for(int i=0;i<size;i++)for(int q=0;q<10;q++)p[q][labels[i][q]-1]+=.9*w[i];return p;}
    public void predict(float[][] out,float[] st){double[][] p=table(weights());for(int i=0;i<10;i++)for(int j=0;j<10;j++)out[i][j]=(float)p[i][j];st[0]=size;st[1]=(float)Math.log1p(t);}
    public void update(int[] draw){OnlineModelsSU2.requireDraw(draw);if(previous!=null){double[] w=weights();double[][] p=table(w);double[] gw=new double[size],grad=new double[10];double mean=0;for(int i=0;i<size;i++){for(int q=0;q<10;q++)if(labels[i][q]==draw[q])gw[i]-=.9/Math.max(1e-12,p[q][draw[q]-1]);mean+=w[i]*gw[i];}for(int i=0;i<size;i++){double gs=w[i]*(gw[i]-mean);for(int q=0;q<10;q++)if(keys[i][q]!=previous[q])grad[q]-=gs;}for(int q=0;q<10;q++)metric[q]=Math.max(.001,Math.min(8,metric[q]-lr*(grad[q]+1e-4*metric[q])));keys[next]=previous.clone();labels[next]=draw.clone();next=(next+1)%CAP;size=Math.min(CAP,size+1);}previous=draw.clone();t++;}
    public void write(DataOutput o)throws IOException{o.writeInt(0x26110001);o.writeDouble(lr);o.writeLong(t);o.writeInt(size);o.writeInt(next);o.writeBoolean(previous!=null);if(previous!=null)for(int x:previous)o.writeInt(x);for(double x:metric)o.writeDouble(x);for(int i=0;i<size;i++){for(int x:keys[i])o.writeInt(x);for(int x:labels[i])o.writeInt(x);}}
    public void read(DataInput in)throws IOException{if(in.readInt()!=0x26110001||in.readDouble()!=lr)throw new IOException("F11_ABI");t=in.readLong();size=in.readInt();next=in.readInt();if(t<0||size<0||size>CAP||next<0||next>=CAP)throw new IOException("F11_STATE");previous=null;if(in.readBoolean()){previous=new int[10];for(int i=0;i<10;i++)previous[i]=in.readInt();OnlineModelsSU2.requireDraw(previous);}for(int i=0;i<10;i++){metric[i]=in.readDouble();if(!Double.isFinite(metric[i])||metric[i]<.001||metric[i]>8)throw new IOException("F11_METRIC");}for(int i=0;i<size;i++){for(int j=0;j<10;j++)keys[i][j]=in.readInt();for(int j=0;j<10;j++)labels[i][j]=in.readInt();OnlineModelsSU2.requireDraw(keys[i]);OnlineModelsSU2.requireDraw(labels[i]);}}
}
